RD=$(ls -dt ~/.factory/runs/multi-repo-delivery-bookkeeping-prs-* | head -1) && tail -3 "$RD/session.jsonl" | python3 -c "
import json,sys
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: o=json.loads(line)
    except: continue
    m=o.get('message',{})
    role=m.get('role')
    if role=='toolResult':
        c=m.get('content')
        txt=''
        if isinstance(c,list):
            for p in c[:2]:
                if p.get('type')=='text': txt=p['text'][:200].replace(chr(10),' ')
        print(f\"[toolResult] {m.get('toolName')}: {txt}\")
    elif role=='assistant':
        c=m.get('content')
        for p in (c if isinstance(c,list) else []):
            if p.get('type')=='text': print(f\"[assistant] {p['text'][:200].replace(chr(10),' ')}\")
            elif p.get('type')=='toolCall': print(f\"[toolCall] {p.get('name')}\")
"

RD=$(ls -dt ~/.factory/runs/multi-repo-delivery-bookkeeping-prs-* | head -1) && tail -12 "$RD/session.jsonl" | python3 -c "
import json,sys
recs=[]
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: recs.append(json.loads(line))
    except: pass
for o in recs:
    m=o.get('message',{})
    role=m.get('role')
    ts=o.get('timestamp','')[11:19]
    if role=='assistant':
        c=m.get('content',[])
        for p in (c if isinstance(c,list) else []):
            t=p.get('type')
            if t=='text': print(f\"{ts} [A] {p['text'][:160].replace(chr(10),' ')}\")
            elif t=='toolCall': print(f\"{ts} [CALL {p.get('name')}] {str(p.get('arguments'))[:160]}\")
    elif role=='toolResult':
        c=m.get('content')
        txt=''
        if isinstance(c,list):
            for p in c:
                if p.get('type')=='text': txt+=p['text']
        print(f\"{ts} [RES {m.get('toolName')}] {txt[:160].replace(chr(10),' ')} err={m.get('isError')}\")
"

