    if m.get('role')=='assistant':
        c=m.get('content',[])
        for p in (c if isinstance(c,list) else []):
            if p.get('type')=='text':
                print('---'); print(p['text'][:300].replace(chr(10),' '))
                n+=1; break
        if n>=4: break
"

