RD=$(ls -dt ~/.factory/runs/multi-repo-delivery-bookkeeping-prs-* | head -1) && tail -5 "$RD/session.jsonl" | python3 -c "
import json,sys
for line in sys.stdin:
    line=line.strip()
    if not line: continue
    try: o=json.loads(line)
    except: continue
    t=o.get('type')
    if t=='message':
        m=o.get('message',{})
        role=m.get('role')
        if role=='assistant':
            for p in (m.get('content') or []):
                if p.get('type')=='text': print('A:', p['text'][:150].replace(chr(10),' '))
                elif p.get('type')=='toolCall': print('CALL:', p.get('name'), str(p.get('arguments'))[:150])
        elif role=='toolResult':
            c=m.get('content')
            txt=''.join(x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text') if isinstance(c,list) else ''
            print('RES:', m.get('toolName'), '| err:', m.get('isError'), '|', txt[-120:].replace(chr(10),' '))
" 2>&1 | tail -8; echo "=== recent unique tool calls (last 60 lines dedup) ==="; tail -60 "$RD/session.jsonl" | python3 -c "
import json,sys
seen=[]
for line in sys.stdin:
    try: o=json.loads(line)
    except: continue
    m=o.get('message',{})
    if m.get('role')=='assistant':
        for p in (m.get('content') or []):
            if p.get('type')=='toolCall':
                a=str(p.get('arguments',''))
                seen.append(a[:110])
for s in seen[-6:]: print('*', s.replace(chr(10),' '))
"

RD=$(ls -dt ~/.factory/runs/multi-repo-delivery-bookkeeping-prs-* | head -1) && python3 -c "
import json
calls=[]; texts=[]
with open('$RD/session.jsonl') as f:
    for line in f:
        try: o=json.loads(line)
        except: continue
        if o.get('type')=='tool_execution_start':
            calls.append((o.get('toolName'), str(o.get('args',{}).get('command',''))[:150]))
        elif o.get('type')=='message_end':
            m=o.get('message',{})
            if m.get('role')=='assistant':
                for p in (m.get('content') or []):
                    if p.get('type')=='text': texts.append(p['text'][:150].replace(chr(10),' '))
print('total tool executions:', len(calls))
for t,c in calls[-6:]: print('CALL:', t, '|', c)
print('--- last texts ---')
for t in texts[-3:]: print('A:', t)
"

